// @vitest-environment node
/**
 * `supportsFieldOverrides` is what the UI offers: the Manual Override table of the Schemas tab, and the alerts about stored overrides.
 * A target may say true only when its generation APPLIES a stored override to what it writes. Every target is generated by the TypeSpec
 * CLI emitters (src/lib/typespec-official), which do not read `schemaTargetTypeOverrides`: an override of a column type was saved, the
 * page said "schema regenerated", and the DDL did not change (docs/testing/known-defects.md, KD-001). Until the emitters take the
 * overrides, no target offers them.
 */
import { readdirSync, readFileSync } from "node:fs";
import path from "node:path";
import { describe, expect, it } from "vitest";
import { getSchemaTargetCatalog, getSchemaTargetDefinition } from "@/lib/schema-targets/catalog";

const EMITTER_SERVICE_DIR = path.join(process.cwd(), "src/lib/typespec-official");

describe("supportsFieldOverrides", () => {
  it.each(["bigquery", "spanner", "postgresql"])("%s does not offer a per-field type override (its emitter ignores one)", (key) => {
    expect(getSchemaTargetDefinition(key)?.supportsFieldOverrides).toBe(false);
  });

  it("is false for every target while the emitters of the TypeSpec CLI path do not read the overrides", () => {
    const readsOverrides = readdirSync(EMITTER_SERVICE_DIR)
      .filter((file) => file.endsWith(".ts"))
      .some((file) => /schemaTargetTypeOverrides|typeOverrides|effectiveMappedType/.test(readFileSync(path.join(EMITTER_SERVICE_DIR, file), "utf8")));
    const offering = getSchemaTargetCatalog().filter((target) => target.supportsFieldOverrides).map((target) => target.key);
    if (readsOverrides) {
      // Someone wired the overrides into the emitters: the flag may be true for the targets they apply to (and this test should say which).
      expect(offering.length).toBeGreaterThan(0);
    } else {
      expect(offering).toEqual([]);
    }
  });
});
